const STYLES_DB = [{"num":"01","name":"Neo-Brutalism","nameZh":"新野兽派","category":"pop","categoryZh":"潮流与趣味","family":"现代极简与数字科技","familyId":"01-现代极简与数字科技","subtitle":"高对比粗黑描边、硬投影与高饱和波普调色，强烈的实体触觉冲击","philosophy":"打破过度平滑的现代审美疲劳，以坦荡、原始、高物理感的设计表达数字世界的真实自信与叛逆。","bestFor":"Z世代潮玩电商、创意设计社区、潮流背单词/打卡工具、独立开发者主页。","keywords":["high contrast","3px solid black border","box-shadow: 4px 4px 0 #000","acid yellow #FFE600","bold grotesque font","chunky tactile buttons","sticker badges"],"colors":[{"name":"Acid Yellow","hex":"#FFE600"},{"name":"Electric Cyan","hex":"#4DEEEA"},{"name":"Pitch Black","hex":"#000000"},{"name":"Pure White","hex":"#FFFFFF"},{"name":"Neon Coral","hex":"#FF5E7E"}],"prompt":"Design a mobile app screen in Neo-Brutalism style. Use 3px solid black borders (#000000), hard unblurred drop-shadows (box-shadow: 4px 4px 0px #000), bright pop accent colors like acid yellow (#FFE600) and electric cyan (#4DEEEA). Employ bold grotesque typography, chunky tactile cards, solid black pill badges, and high-contrast tactile buttons with active press states.","cssSnippet":".neo-card {
  background: #FFFFFF;
